import hashlib
from Crypto.Cipher import AES

def scrypt_derive_key(passphrase: str) -> bytes:
    # Based on scrypt(hash(password), NO salt): N=16384, r=8, p=1, output=32
    return hashlib.scrypt(passphrase.encode(), salt=b'', n=16384, r=8, p=1, dklen=32)

# Rebuild concatenated original ID string
with open('/tmp/original_id_list.txt') as f:
    ids = [line.strip() for line in f if line.strip()]
concat = ''.join(ids)
key = scrypt_derive_key(concat)

with open('/tmp/handout_extracted/password.bin', 'rb') as f:
    data = f.read()
nonce = data[:16]
tag = data[16:32]
ciphertext = data[32:]

cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
try:
    plaintext = cipher.decrypt_and_verify(ciphertext, tag)
except Exception as e:
    print('Decryption failed:', e)
    exit(1)

def is_flag(pt):
    try:
        pt = pt.decode()
    except Exception:
        return False
    return pt.startswith('flag{') and pt.endswith('}')

if is_flag(plaintext):
    print(plaintext.decode())
else:
    with open('/tmp/password_decrypted.txt', 'wb') as fout:
        fout.write(plaintext)
    print('Saved decrypted password to /tmp/password_decrypted.txt.')

